"""Post-autogenerate patch: replace the autogenerated `downgrade()` of the
baseline migration with a FK-safe table drop.

Why: MySQL refuses to DROP INDEX when a FOREIGN KEY is bound to it
(errno 1553 — e.g. ix_plan_change_logs_trip_id), so Alembic's per-index
downgrade statements fail halfway and leave the schema inconsistent.
Dropping the TABLE removes its indexes implicitly.

The baseline migration is always the LAST file in alembic/versions and
`downgrade()` is always the final function, which is what this patch relies
on. Run automatically by scripts/regen_baseline.sh-style flows; safe to run
twice (idempotent — it matches from `def downgrade()` to EOF).

Usage (from backend/):  python scripts/fix_baseline_downgrade.py [path]
"""
import sys
from pathlib import Path

TABLES = [
    # children first (FK targets in parentheses)
    "payment_splits",        # → payments
    "trip_profiles",         # → trips
    "trip_place_selections", # → trips
    "reviews",               # → trips, guides, users
    "replanning_logs",       # → trips
    "plan_change_logs",      # → trips
    "budget_adjustments",    # → trips
    "payments",              # → trips, users
    "offline_packages",      # → trips
    "itineraries",           # → trips
    "guide_assignments",     # → trips, guides, managers
    "chat_messages",         # → trips
    "trips",                 # → users, locations
    "users",                 # → identities, locations
    "managers",              # → identities
    "guides",                # → identities
    "admins",                # → identities
    "locations",
    "identities",
    "contact_messages",
    "audit_logs",
]

DOWNGRADE = '''def downgrade() -> None:
    """Drop the entire baseline schema.

    Alembic's autogenerated version emitted per-index DROP statements first,
    but MySQL refuses to drop an index a FOREIGN KEY is bound to (errno 1553).
    Dropping the TABLE removes its indexes implicitly, so this downgrade drops
    tables only, children first, with foreign-key checks disabled as a safety
    net. (Applied by scripts/fix_baseline_downgrade.py — keep in sync with the
    model table list if tables are ever removed.)
    """
    tables = {tables!r}
    op.execute("SET FOREIGN_KEY_CHECKS=0")
    try:
        for table in tables:
            op.execute(f"DROP TABLE IF EXISTS `{table}`")
    finally:
        op.execute("SET FOREIGN_KEY_CHECKS=1")
    # ### end Alembic commands ###
'''.replace("{tables!r}", repr(TABLES))


def main() -> None:
    path = Path(sys.argv[1]) if len(sys.argv) > 1 else (
        Path(__file__).resolve().parent.parent / "alembic" / "versions"
    )
    if path.is_dir():
        files = sorted(path.glob("*.py"))
        if len(files) != 1:
            raise SystemExit(f"expected exactly one baseline file, found {len(files)}")
        path = files[0]

    text = path.read_text(encoding="utf-8")
    marker = "def downgrade() -> None:"
    if marker not in text:
        raise SystemExit(f"no downgrade() found in {path}")
    head = text.split(marker, 1)[0]
    path.write_text(head + DOWNGRADE, encoding="utf-8")

    # Guard: never leave per-index drops behind (they break MySQL downgrades).
    final = path.read_text(encoding="utf-8")
    if "drop_index" in final.split(marker, 1)[1]:
        raise SystemExit("patch failed: drop_index statements remain in downgrade()")
    compile(final, str(path), "exec")
    print(f"patched downgrade() in {path.name} ({len(TABLES)} tables)")


if __name__ == "__main__":
    main()
